/* Notebook Fighters service worker (generated by scripts/build-sw.mjs from scripts/sw-template.js).
 *
 * After one visit the whole game works with no internet: every page, script, style, sound and the
 * web fonts are cached at install. Pages and page payloads are network-first (3 s timeout, then the
 * saved copy), so a phone on a hotspot with no internet still opens the game; the hashed build files
 * and the sounds are cache-first.
 * Never touched: /api/* (online rooms: always the network) and other sites. /r/CODE (a room link)
 * goes to the network and, offline, falls back to the saved /online page.
 */
const VERSION = "__VERSION__";
const PRECACHE = __PRECACHE__;
const PAGES = __PAGES__;
const OPTIONAL = __OPTIONAL__;
const CACHE = `nf-precache-${VERSION}`;
const FONTS = "nf-fonts-v1";
const FONT_CSS = "https://fonts.googleapis.com/css2?family=Patrick+Hand&family=Source+Sans+3:wght@400;600;700&display=swap";

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // fresh copies (not the HTTP cache), all-or-nothing except the optional ones
      await Promise.all(
        PRECACHE.map(async (url) => {
          try {
            const res = await fetch(url, { cache: "reload", credentials: "same-origin" });
            if (!res.ok || res.redirected) throw new Error(`${url}: ${res.status}`);
            await cache.put(url, res);
          } catch (e) {
            if (!OPTIONAL.includes(url)) throw e;
          }
        }),
      );
      // the web fonts (best effort: the game falls back to system fonts)
      try {
        const fonts = await caches.open(FONTS);
        const css = await fetch(FONT_CSS, { mode: "cors" });
        if (css.ok) {
          const text = await css.clone().text();
          await fonts.put(FONT_CSS, css);
          const urls = [...text.matchAll(/url\((https:\/\/fonts\.gstatic\.com\/[^)]+)\)/g)].map((m) => m[1]);
          await Promise.all(urls.map((u) => fetch(u, { mode: "cors" }).then((r) => (r.ok ? fonts.put(u, r) : undefined)).catch(() => {})));
        }
      } catch {
        // offline or blocked
      }
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // keep this version and the one before it (a tab still running the old pages can finish loading)
      const old = (await caches.keys()).filter((k) => k.startsWith("nf-precache-") && k !== CACHE).sort();
      await Promise.all(old.slice(0, -1).map((k) => caches.delete(k)));
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("message", (event) => {
  if (event.data === "nf:status") event.source?.postMessage({ type: "nf:status", version: VERSION, files: PRECACHE.length });
});

const pageFor = (path) => {
  const p = path.replace(/\/+$/, "").replace(/\.html$/, "") || "/";
  if (PAGES.includes(p)) return p;
  if (p.startsWith("/r/")) return "/online";
  return null;
};

async function fromCache(request, url) {
  return (await caches.match(url, { ignoreSearch: true, ignoreVary: true })) ?? (await caches.match(request, { ignoreSearch: true, ignoreVary: true }));
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);

  if (url.origin === "https://fonts.googleapis.com" || url.origin === "https://fonts.gstatic.com") {
    event.respondWith(
      (async () => {
        const hit = await caches.match(request, { ignoreVary: true });
        if (hit) return hit;
        try {
          const res = await fetch(request);
          if (res.ok) (await caches.open(FONTS)).put(request, res.clone());
          return res;
        } catch (e) {
          // offline and never cached: an empty stylesheet, so the page quietly uses its fallback fonts
          if (url.origin === "https://fonts.googleapis.com") return new Response("", { headers: { "content-type": "text/css", "cache-control": "no-store" } });
          throw e;
        }
      })(),
    );
    return;
  }
  if (url.origin !== self.location.origin) return;
  // online rooms and the Worker's own routes: never cached, never intercepted
  if (url.pathname.startsWith("/api/")) return;

  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        const page = pageFor(url.pathname);
        try {
          const ctrl = new AbortController();
          const t = setTimeout(() => ctrl.abort(), 3000);
          const res = await fetch(request, { signal: ctrl.signal });
          clearTimeout(t);
          return res;
        } catch (e) {
          const hit = page && (await caches.match(page, { ignoreSearch: true }));
          if (hit) return hit;
          const nf = await caches.match("/404", { ignoreSearch: true });
          if (nf) return nf;
          throw e;
        }
      })(),
    );
    return;
  }
  if (url.pathname.startsWith("/r/")) return;

  // hashed build files and the sounds never change under a URL: cache first
  if (url.pathname.startsWith("/_next/static/") || url.pathname.startsWith("/sfx/")) {
    event.respondWith(
      (async () => {
        const hit = await fromCache(request, url.pathname);
        if (hit) return hit;
        return fetch(request);
      })(),
    );
    return;
  }
  // the rest (page payloads for client-side navigation, the manifest, icons): fresh when online, saved copy offline
  event.respondWith(
    (async () => {
      try {
        const ctrl = new AbortController();
        const t = setTimeout(() => ctrl.abort(), 3000);
        const res = await fetch(request, { signal: ctrl.signal });
        clearTimeout(t);
        return res;
      } catch (e) {
        const hit = await fromCache(request, url.pathname);
        if (hit) return hit;
        throw e;
      }
    })(),
  );
});
